package com.campus.personnel.domain;
import java.time.Instant; import java.util.UUID; import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.*;
class FacultyStaffMemberTest { @Test void normalizesAndValidatesPersonnel(){ FacultyStaffMember member=FacultyStaffMember.create(UUID.randomUUID()," P001 "," Person One ","ONE@campus.example",PersonnelType.FACULTY,UUID.randomUUID(),PersonnelStatus.ACTIVE,Instant.now());assertThat(member.personnelNumber()).isEqualTo("P001");assertThat(member.email()).isEqualTo("one@campus.example");assertThatThrownBy(()->FacultyStaffMember.create(UUID.randomUUID(),"x","Name",null,PersonnelType.STAFF,UUID.randomUUID(),PersonnelStatus.ACTIVE,Instant.now())).isInstanceOf(FacultyStaffMember.InvalidFacultyStaffMemberException.class);}}
